# ──────────────────────────────────────────────────────────────────────────────
# config.py — USER-MANAGED hyperparameters & runtime settings
# ──────────────────────────────────────────────────────────────────────────────
# This file is **NOT** auto-generated. It is safe to edit by hand.
#
# The auto-generated system prompts and schema constants live in ``prompts.py``
# (regenerated by ``python gen_system_prompt.py`` from the live Neo4j schema).
# Keeping the two files separate prevents ``setup_project.py`` from
# overwriting the LLM configuration / pipeline knobs every time the schema
# is re-derived.
#
# Layout
# ──────
#   1. LLM configuration (per pipeline stage)
#   2. Runtime constants (sampling, validation, threading)
#   3. NER pipeline mode
# ──────────────────────────────────────────────────────────────────────────────

# ──────────────────────────────────────────────────────────────────────────────
# LLM configuration  (per pipeline stage)
# ──────────────────────────────────────────────────────────────────────────────
# Each pipeline stage has its own LLM "slot" so experiments can mix providers
# (e.g. GPT for NER, Claude Opus for Cypher generation) without code changes.
#
# Schema for every entry:
#   {
#     "provider":    "openai" | "azure" | "anthropic" | "auto",
#     "model":       <model-name-or-deployment>,
#     "temperature": <float>,         # optional, default 0
#     # Anything else is forwarded verbatim to the chat-model constructor.
#   }
#
# ``agent_helper.build_llm(**LLM_CONFIG)`` consumes these dicts and returns a
# concrete ``BaseChatModel`` — see ``agent_helper.ner_llm`` / ``qa_llm`` /
# ``cypher_llm`` for the resolved singletons.
#
# Examples
# --------
#   NER_LLM_CONFIG    = {"provider": "openai",    "model": "gpt-4.1"}
#   CYPHER_LLM_CONFIG = {"provider": "anthropic", "model": "claude-opus-4-20250514"}
#   QA_LLM_CONFIG     = {"provider": "openai",    "model": "gpt-4o-mini"}
# ──────────────────────────────────────────────────────────────────────────────

NER_LLM_CONFIG: dict = {
    "provider":    "anthropic",
    "model":       "claude-opus-4-20250514",
    "temperature": 0,
}

QA_LLM_CONFIG: dict = {
    "provider":    "openai",
    "model":       "gpt-4.1",
    "temperature": 0,
}

CYPHER_LLM_CONFIG: dict = {
    "provider":    "openai",
    "model":       "gpt-4.1",
    "temperature": 0,
}

# Legacy default — used by any code path that imports ``agent_helper.llm``
# without specifying a stage.  Defaults to the same setup as NER.
DEFAULT_LLM_CONFIG: dict = dict(NER_LLM_CONFIG)


# ──────────────────────────────────────────────────────────────────────────────
# Runtime constants
# ──────────────────────────────────────────────────────────────────────────────

MAX_THREAD            = 5    # parallel tool calls in the NER agent
DEFAULT_TOP_K         = 5    # FAISS tool-selection top-k
TOOL_TOP_K            = 10   # fulltext search top-k per tool call
STABILITY_K           = 3    # consecutive stable validation rounds before stopping
MAX_VALIDATION_ROUNDS = 20   # hard cap on validation rounds per property pair
SAMPLE_T              = 20   # sample size t per round (sample_property_values)
CAP_MULTIPLIER        = 1000    # scan cap = t * CAP_MULTIPLIER (cheap over-fetch for random sampling)


# ──────────────────────────────────────────────────────────────────────────────
# NER pipeline mode
# ──────────────────────────────────────────────────────────────────────────────
# Controls how (or whether) the ReAct NER agent runs in front of the Cypher
# generator.  The same three switches drive both ``ner_agent_auto.ask_auto``
# (the full pipeline) and the CypherBench evaluator
# (``metrics_CypherBench.evaluate_dataset``).
#
#   "full"      — Default.  Register every generated @tool — node property,
#                 relation property, AND structural traversal — and run the
#                 ReAct NER agent normally.  This is the original behaviour
#                 and produces the richest entity-filter dictionary.
#
#   "node_only" — Register **only** the node-property tools generated in
#                 ``generated_node_tools.py``; the relation tools in
#                 ``generated_rel_tools.py`` are skipped entirely.  Use this
#                 to ablate the contribution of relation-aware NER, or when
#                 the target schema's relation tools are noisy.
#
#   "no_ner"    — Bypass the NER ReAct agent altogether.  ``ask_auto``
#                 short-circuits with an empty entity dict and feeds only
#                 ``{schema}`` + ``{question}`` to ``GraphCypherQAChain``.
#                 Use this to measure how much the NER stage actually buys
#                 you on a given dataset / model combination.
#
# The setting can be overridden per-call by passing ``mode=...`` to
# ``ner_agent_auto.ask_auto`` / ``get_ner_auto`` / ``select_tools_for_query``,
# or via ``--ner-mode`` on the ``metrics_CypherBench`` CLI.
# ──────────────────────────────────────────────────────────────────────────────

NER_MODE: str = "full"     # "full" | "node_only" | "no_ner"

# Allowed values — kept centrally so callers can validate user input
# without hard-coding the literal strings.
NER_MODES = ("full", "node_only", "no_ner")
